import { validateNodes } from './validate-nodes.mjs';

export function planBuild(nodes) {
  validateNodes(nodes);
  if (nodes.length === 0) {
    return [];
  }
  const orderIndex = new Map();
  nodes.forEach((node, index) => {
    orderIndex.set(node.id, index);
  });
  const depsById = new Map();
  for (const node of nodes) {
    depsById.set(node.id, [...new Set(node.dependsOn || [])]);
  }
  const scheduled = new Set();
  const result = [];
  while (result.length < nodes.length) {
    let picked = null;
    let pickedIndex = Infinity;
    for (const node of nodes) {
      if (scheduled.has(node.id)) continue;
      const deps = depsById.get(node.id);
      if (deps.every((dep) => scheduled.has(dep))) {
        const idx = orderIndex.get(node.id);
        if (idx < pickedIndex) {
          pickedIndex = idx;
          picked = node.id;
        }
      }
    }
    if (picked === null) {
      throw new Error('cycle detected');
    }
    scheduled.add(picked);
    result.push(picked);
  }
  return result;
}

