export function validateNodes(nodes) {
  if (!Array.isArray(nodes)) {
    throw new TypeError('nodes must be an array');
  }
  const seenIds = new Set();
  const ids = new Set();
  for (const node of nodes) {
    if (node === null || typeof node !== 'object' || Array.isArray(node)) {
      throw new TypeError('invalid node');
    }
    if (typeof node.id !== 'string' || node.id.length === 0) {
      throw new TypeError('invalid node id');
    }
    const dependsOn = node.dependsOn === undefined ? [] : node.dependsOn;
    if (!Array.isArray(dependsOn)) {
      throw new TypeError('dependsOn must be an array');
    }
    if (seenIds.has(node.id)) {
      throw new Error('duplicate node id');
    }
    seenIds.add(node.id);
    ids.add(node.id);
    const uniqueDeps = new Set();
    for (const dep of dependsOn) {
      if (typeof dep !== 'string' || dep.length === 0) {
        throw new TypeError('invalid dependency id');
      }
      uniqueDeps.add(dep);
    }
    if (uniqueDeps.has(node.id)) {
      throw new Error('cycle detected');
    }
  }
  for (const node of nodes) {
    const dependsOn = node.dependsOn === undefined ? [] : node.dependsOn;
    for (const dep of new Set(dependsOn)) {
      if (!ids.has(dep)) {
        throw new Error('missing dependency');
      }
    }
  }
  assertAcyclic(nodes);
  return nodes;
}

function assertAcyclic(nodes) {
  const deps = new Map();
  for (const node of nodes) {
    deps.set(node.id, [...new Set(node.dependsOn || [])]);
  }
  const visiting = new Set();
  const visited = new Set();
  function visit(id) {
    if (visited.has(id)) return;
    if (visiting.has(id)) {
      throw new Error('cycle detected');
    }
    visiting.add(id);
    for (const dep of deps.get(id) || []) {
      visit(dep);
    }
    visiting.delete(id);
    visited.add(id);
  }
  for (const node of nodes) {
    visit(node.id);
  }
}

